class Base {
  public:
    virtual void virtualFunc();  // Declares a virtual function, triggering vtable generation
    int dataMember;  // Non-static data member follows vpointer in memory layout
};

class Derived : public Base {
  public:
    void virtualFunc() override;  // Overrides the virtual function, updating the vtable
};  // Implementation note: The compiler adds a vpointer as the first member for both classes.
